window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a2501d21ec002276"]={"versions": [{"id": "FIG-a2501d21ec002276", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Schnittstellendefinition im AUTOSAR-DCM-Modul (Diagnostic Communication Manager). Das Diagramm befindet sich in einem UML-Rahmen <code>class RoutineServices</code> und spezifiziert die Client-Server-Schnittstelle zur Ausführung von Diagnoseroutinen über den UDS-Dienst RoutineControl (0x31).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Schnittstellenklasse (Stereotyp <code>«interface»</code>):</p>\n<ul class=\"fig-list\"><li><code>RoutineServices_&lt;ROUTINENAME&gt;</code>: Parametrisierte Port-Schnittstelle mit drei Operationen:\n<ul class=\"fig-list\"><li><code>RequestResults(return :Std_ReturnType, OutBuffer :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li><li><code>Start(return :Std_ReturnType, InBuffer :uint8*, OutBuffer :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li><li><code>Stop(return :Std_ReturnType, InBuffer :uint8*, OutBuffer :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Die Operationen nutzen Ein- und Ausgabepuffer als Byte-Zeiger (<code>uint8*</code>) sowie einen Zeiger auf den negativen Antwortcode <code>ErrorCode</code> (<code>Dcm_NegativeResponseCodeType*</code>). Alle Operationen liefern einen Rückgabewert vom Typ <code>Std_ReturnType</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikation von Operationen für synchrone oder asynchrone Client-Server-Kommunikation. Es wird kein zeitlicher Ablauf dargestellt. Das Verhalten entspricht den Subfunktionen des UDS-Dienstes 0x31: Starten einer Routine (<code>Start</code>), Stoppen einer Routine (<code>Stop</code>) und Abfragen der Routinenergebnisse (<code>RequestResults</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der AUTOSAR-Port-Schnittstelle für anwendungsspezifische Diagnoseroutinen. Entwickler von SW-Cs müssen für jede zu unterstützende Routine eine Instanz dieser Schnittstelle bereitstellen (P-Port) bzw. das DCM verbindet sich als Client (R-Port), um Diagnoserequests an die entsprechende Software-Komponente weiterzuleiten. Fehlerhafte Ausführungen werden über <code>ErrorCode</code> mit spezifischen NRCs signalisiert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b4d801bf260e4ff7", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Schnittstellendefinition im AUTOSAR-DCM-Modul (Diagnostic Communication Manager). Dargestellt ist die Client-Server-Schnittstelle <code>RoutineServices_&lt;ROUTINENAME&gt;</code> zur Steuerung von Diagnoseroutinen über den UDS-Dienst RoutineControl (0x31).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Schnittstellenklasse (Stereotyp <code>«interface»</code>):</p>\n<ul class=\"fig-list\"><li><code>RoutineServices_&lt;ROUTINENAME&gt;</code>: Parametrisierte Port-Schnittstelle mit drei Operationen:\n<ul class=\"fig-list\"><li><code>RequestResults(return :Std_ReturnType, OutBuffer :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li><li><code>Start(return :Std_ReturnType, InBuffer :uint8*, OutBuffer :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li><li><code>Stop(return :Std_ReturnType, InBuffer :uint8*, OutBuffer :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Die Operationen nutzen Ein- und Ausgabepuffer als Byte-Zeiger (<code>uint8*</code>) sowie einen Zeiger auf den negativen Antwortcode <code>ErrorCode</code> (<code>Dcm_NegativeResponseCodeType*</code>). Alle Operationen liefern einen Rückgabewert vom Typ <code>Std_ReturnType</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikation von Operationen für synchrone oder asynchrone Client-Server-Kommunikation. Es wird kein zeitlicher Ablauf dargestellt. Das Verhalten entspricht den Subfunktionen des UDS-Dienstes 0x31: Starten einer Routine (<code>Start</code>), Stoppen einer Routine (<code>Stop</code>) und Abfragen der Routinenergebnisse (<code>RequestResults</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition der AUTOSAR-Port-Schnittstelle für anwendungsspezifische Diagnoseroutinen. Entwickler von SW-Cs müssen für jede zu unterstützende Routine eine Instanz dieser Schnittstelle bereitstellen (P-Port) bzw. das DCM verbindet sich als Client (R-Port), um Diagnoserequests an die entsprechende Software-Komponente weiterzuleiten. Fehlerhafte Ausführungen werden über <code>ErrorCode</code> mit spezifischen NRCs signalisiert.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a2501d21ec002276", "to": "FIG-b4d801bf260e4ff7", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Der umschließende UML-Diagrammrahmen mit dem Kopf <code>class RoutineServices</code> entfällt im Bildausschnitt; stattdessen ist oben Fließtext angeschnitten.\n</li><li>Der Schnittstellenname <code>RoutineServices_&lt;ROUTINENAME&gt;</code> ist nicht mehr kursiv gesetzt.\n</li></ul>"}]};
